<template>
  <CanvasserFormWrapper title="Identification Documents">
    <AccountFormImageUpload
      label="ID Photos"
      is-multiple
      :clear-input-triggered="clearInputTriggered"
      @on-process-data="setLoadedImages"
    />
    <form
      class="self-center flex flex-col gap-6 flex-auto w-full justify-center max-w-[700px] max-lg:px-0"
      @submit.prevent="onSubmit"
    >
      <FormItemWrapper
        name="id_photo_urls"
        :validate-on-model-update="false"
        :validate-on-blur="false"
        :validate-on-change="false"
        :validate-on-mount="false"
      >
        <template #default="{ slots }">
          <div>
            <AccountImageHolder
              id="id_photo_urls"
              v-model:links="loadedImages"
              :images="loadedImages"
              v-bind="slots.componentField"
              @delete="deleteImage"
              @change:links="(data: string[] | undefined) => slots.setValue(data, false)"
            />
          </div>
        </template>
      </FormItemWrapper>
      <AccountDocumentExamples />
      <FormItemWrapper name="consent" type="checkbox" :unchecked-value="false" :checked-value="true">
        <template #default="{ slots }">
          <div class="flex items-start gap-2">
            <Checkbox id="consent" :model-value="slots.value" v-bind="slots.componentField" />
            <label for="consent" class="text-sm text-muted-foreground leading-tight cursor-pointer">
              I consent to the collection, storage, and processing of my identification documents by the Platform in
              accordance with
              <a href="/privacy-policy" class="text-primary underline hover:no-underline">Privacy Policy</a>. I
              understand this information is required for identity verification purposes and will be handled securely.
            </label>
          </div>
        </template>
      </FormItemWrapper>
      <Button type="submit" class="w-full h-10 col-span-2" :loading="isSettingCanvasserDocuments"
        >Submit Information</Button
      >
    </form>
  </CanvasserFormWrapper>
</template>

<script setup lang="ts">
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import { postCanvasserDocuments, type CanvasserDocumentsRequest } from '~/client';

definePageMeta({
  roles: ['canvasser'],
});

useHead({
  title: 'Canvasser Documents',
});

const loadedImages = ref<Image[]>([]);
const clearInputTriggered = ref<boolean>(false);

const formSchema = toTypedSchema(
  z.object({
    id_photo_urls: z.array(z.string()).refine((val) => val.length > 0, {
      message: 'At least one image is required',
    }),
    consent: z.boolean().refine((val) => val === true, { message: 'You must agree before submitting' }),
  })
);

const { handleSubmit } = useForm({
  validationSchema: formSchema,
  initialValues: {
    id_photo_urls: [],
    consent: false,
  },
});

function setLoadedImages(images: Image[]) {
  loadedImages.value = images;
}

const refreshAccountAndRedirect = useRefreshAccountAndRedirect();

const { mutateAsync: postCanvasserDocumentsData, asyncStatus } = useMutation({
  mutation: (documentsForm: CanvasserDocumentsRequest) =>
    postCanvasserDocuments({
      composable: '$fetch',
      body: {
        ...documentsForm,
      },
    }),
  onSuccess: async () => {
    showToastSuccess('Documents submitted successfully');
    await refreshAccountAndRedirect();
  },
  onError: (error) => {
    console.error('Error setting canvasser document:', error);
    showToastError(error);
  },
});

const isSettingCanvasserDocuments = computed(() => asyncStatus.value === 'loading');

const onSubmit = handleSubmit(async ({ consent: _, ...values }: any) => {
  await postCanvasserDocumentsData(values);
});

function deleteImage(public_url: string) {
  loadedImages.value = loadedImages.value.filter((image) => public_url !== image.public_url);
  if (loadedImages.value.length === 0) clearInputTriggered.value = !clearInputTriggered.value;
}
</script>

<style scoped lang="scss"></style>
