<template>
  <form
    class="self-center flex flex-col gap-6 flex-auto w-full justify-center max-w-[700px] max-lg:px-0 image-upload-form"
  >
    <FormItemWrapper
      :label="label"
      name="photos"
      :validate-on-model-update="false"
      :validate-on-blur="false"
      :validate-on-change="false"
    >
      <template #default="{ slots }">
        <Input
          id="photos"
          type="file"
          :multiple="isMultiple"
          :disabled="disabled"
          class="cursor-pointer"
          accept="image/png, image/jpeg, image/jpeg"
          @change="
            async (event: Event) => {
              slots.handleChange(event);
              await submit();
            }
          "
        />
      </template>
    </FormItemWrapper>
  </form>
</template>

<script setup lang="ts">
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import type { FileUploadResponse } from '~/client';

interface Emits {
  (e: 'onProcessData', event: Image[]): void;
}

const emits = defineEmits<Emits>();

interface Props {
  clearInputTriggered?: boolean;
  label?: string;
  isMultiple?: boolean;
  disabled?: boolean;
}

const props = defineProps<Props>();

const multipleInputSchema = toTypedSchema(
  z.object({
    photos: z
      .instanceof(File)
      .array()
      .refine((list) => list.length <= 10, 'Maximum 10 files allowed')
      .refine(
        (files) => {
          const allowedTypes: { [key: string]: boolean } = {
            'image/jpeg': true,
            'image/jpg': true,
            'image/png': true,
          };
          return files.every((file) => allowedTypes[file.type]);
        },
        { message: 'Invalid file type. Allowed types: JPEG, JPG, PNG' }
      )
      .refine(
        (files) => {
          return files.every((file) => file.size <= 10 * 1024 * 1024);
        },
        {
          message: 'File size should not exceed 10MB',
        }
      ),
  })
);

const inputSchema = toTypedSchema(
  z.object({
    photos: z
      .instanceof(File)
      .refine(
        (file) => {
          const allowedTypes: { [key: string]: boolean } = {
            'image/jpeg': true,
            'image/jpg': true,
            'image/png': true,
          };
          return allowedTypes[file.type];
        },
        { message: 'Invalid file type. Allowed types: JPEG, JPG, PNG' }
      )
      .refine(
        (file) => {
          return file.size <= 10 * 1024 * 1024;
        },
        {
          message: 'File size should not exceed 10MB',
        }
      ),
  })
);

const { handleSubmit: submitInput } = useForm({
  validationSchema: props.isMultiple ? multipleInputSchema : inputSchema,
  initialValues: {
    photos: [],
  },
});

const { uploadFileData } = useUploadFile();

const submit = submitInput(async (values) => {
  let files = values.photos;

  if (files.length === 0) {
    emits('onProcessData', []);
    return;
  }

  if (!Array.isArray(files)) {
    files = [files];
  }

  let processedFiles: Image[] = [];
  const uploadPromises: Array<Promise<FileUploadResponse> | null> = [];
  files.forEach((file, index) => {
    processedFiles.push({
      private_url: '',
      public_url: '',
      isLoading: true,
      uploadResult: uploadFileData({ file: file }),
    });
    if (processedFiles[index].uploadResult) uploadPromises.push(processedFiles[index].uploadResult);
  });
  await Promise.allSettled(uploadPromises).then((results) => {
    results.forEach((result, index) => {
      if (result.status === 'rejected') {
        processedFiles[index].uploadResult = null;
        showToastError(files[index].name, 'Failed to upload file: ');
      } else if (result.value) {
        processedFiles[index] = {
          ...processedFiles[index],
          private_url: result.value?.private_url,
          public_url: result.value?.public_url,
          isLoading: false,
        };
      }
    });
    processedFiles = processedFiles.filter((file) => file.uploadResult);
    emits('onProcessData', processedFiles);
  });
});

function clearInput() {
  const imageInput = document.querySelector('.image-upload-form input[type="file"]') as HTMLInputElement;
  if (imageInput) {
    imageInput.value = '';
    imageInput.removeAttribute('disabled');
    emits('onProcessData', []);
  }
}

watch(
  () => props.clearInputTriggered,
  () => {
    clearInput();
  }
);
</script>

<style scoped lang="scss"></style>
