<template>
  <div :id="id" class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-2 mt-2">
    <div v-if="placeholderImage && images.length === 0" class="w-full">
      <img :src="placeholderImage" alt="Profile example" />
    </div>
    <p v-if="images.length === 0 && !isNoImageState">No Images loaded</p>
    <ImagesPreview
      v-for="image in images"
      :key="image.public_url"
      :url="image.public_url"
      :is-loading="image.isLoading"
      :is-square="isSquare"
      class="min-h-48 lg:min-h-40 h-fit"
      @delete="() => $emit('delete', image.public_url)"
    />
  </div>
</template>

<script setup lang="ts">
interface Emit {
  (e: 'delete', public_url: string): void;
  (e: 'change:links', value: string[] | undefined): void;
}

const emits = defineEmits<Emit>();

interface Props {
  id: string;
  images: Image[];
  isNoImageState?: boolean;
  placeholderImage?: string;
  placeholderImageAlt?: string;
  isSquare?: boolean;
}

defineProps<Props>();

const model = defineModel<Image[]>('links');

watch(model, (newValue) => {
  emits(
    'change:links',
    newValue?.map((image) => image.private_url)
  );
});
</script>

<style scoped lang="scss"></style>
